class Widget {
    struct Impl;                                // handle/body: one pointer is the state
    std::unique_ptr<Impl> p_;
public:
    Widget(Widget&&) noexcept = default;        // let std::swap be non-throwing
    Widget& operator=(Widget&&) noexcept = default;

    friend void swap(Widget& a, Widget& b) noexcept {   // ADL customization point
        std::swap(a.p_, b.p_);                  // no allocation, cannot throw
    }
};
static_assert(std::is_nothrow_swappable_v<Widget>);

