namespace orange {
class String {
    char* str_;
public:
    void swap(String& s) /* throw() */ {
        char* t = str_; str_ = s.str_; s.str_ = t;
    }
};
void swap(String& a, String& b) { a.swap(b); }             // ADL
}
namespace std { template<> inline void swap(orange::String& a, orange::String& b) { a.swap(b); } }

struct State { std::string cfg; int limit; };
std::atomic<std::shared_ptr<const State>> live;   // C++20

void publish(std::shared_ptr<const State> next) noexcept {  // commit step
    live.exchange(std::move(next));               // readers keep the old state alive
}
std::shared_ptr<const State> snapshot() noexcept { return live.load(); }
